    "code": "def summarize_results(results):
    summary = {"passed": 0, "failed": 0, "skipped": 0}
    for result in results:
        status = result.get("status")
        if status == "passed":
            summary["passed"] += 1
        elif status == "failed":
            summary["failed"] += 1
        elif status == "skipped":
            summary["skipped"] += 1
        else:
            raise ValueError(f'Unknown status: {status}')
    total_tests = summary["passed"] + summary["failed"] + summary["skipped"]
    summary["pass_rate"] = summary["passed"] / total_tests if total_tests else 0.0
    return summary
",
